package com.bridge.quartercore;
import org.junit.jupiter.api.Test;import java.util.*;import java.util.concurrent.atomic.*;
import static org.junit.jupiter.api.Assertions.*;import static com.bridge.quartercore.NativeSheetsModel.*;import static com.bridge.quartercore.NarrowQuarterPoc.*;
class NativeClaimCloseWaitTest {
 static final GoogleSheetsBinding B=PlannedMaintenanceStartupFactoryTest.B;
 record Fixture(Book open,Book closed){}
 static Fixture fixture(boolean business,boolean bootstrap)throws Exception{Book initial=JournaledNativeWriterTest.initial().b;if(bootstrap){initial=initial.copy();initial.metadata.clear();initial=LegacyToNativeCutoverPlan.prepare(JournaledNativeWriterTest.BINDING,initial,JournaledNativeWriterTest.CLOCK).expected();}var m=new JournaledNativeWriterTest.Memory(initial);try(var s=new Service(new JournaledNativeTransport(m,JournaledNativeWriterTest.BINDING,JournaledNativeWriterTest.CLOCK),JournaledNativeWriterTest.CLOCK,JournaledNativeWriterTest.BINDING,"w-"+UUID.randomUUID(),Limits.defaults())){s.start();assertEquals(State.OPEN,s.state());if(business){var identity=m.b.sheet("auth_identities").rows.get(1);assertEquals(NativeWriterAdapter.Outcome.VERIFIED,new NativeWriterAdapter(s).identity("normal-profile",identity.get(0),identity.get(1),"Changed nickname","test@example.com").outcome());}var open=m.b.copy();s.cleanClose();assertEquals(State.CLOSED,s.state());return new Fixture(open,m.b.copy());}}
 @Test void claimBusinessAndFirstEmptyOwnerBootstrapCanClose()throws Exception{for(var f:List.of(fixture(false,false),fixture(true,false),fixture(false,true))){var reads=new AtomicInteger();var nanos=new AtomicLong();var result=NativeClaimCloseWait.read(B,JournaledNativeWriterTest.CLOCK,()->reads.getAndIncrement()==0?f.open():f.closed(),()->{},nanos::get,()->nanos.addAndGet(15_000_000_000L));assertEquals(2,reads.get());assertEquals(JournalSessionAuthority.fullToken(f.closed()),JournalSessionAuthority.fullToken(result));}}
 @Test void legitimateBusinessWritesBetweenReadsThenClose()throws Exception{var m=JournaledNativeWriterTest.initial();try(var s=new Service(new JournaledNativeTransport(m,JournaledNativeWriterTest.BINDING,JournaledNativeWriterTest.CLOCK),JournaledNativeWriterTest.CLOCK,JournaledNativeWriterTest.BINDING,"w-"+UUID.randomUUID(),Limits.defaults())){s.start();var before=m.b.copy();var identity=m.b.sheet("auth_identities").rows.get(1);new NativeWriterAdapter(s).identity("later-profile",identity.get(0),identity.get(1),"Later nickname","test@example.com");s.cleanClose();var after=m.b.copy();var reads=new AtomicInteger();assertEquals(JournalSessionAuthority.fullToken(after),JournalSessionAuthority.fullToken(NativeClaimCloseWait.read(B,JournaledNativeWriterTest.CLOCK,()->reads.getAndIncrement()==0?before:after,()->{},()->0,()->{})));}}
 @Test void deadlineAndLateClosedAreRejected()throws Exception{var f=fixture(false,false);var nanos=new AtomicLong();var reads=new AtomicInteger();assertThrows(RuntimeException.class,()->NativeClaimCloseWait.read(B,JournaledNativeWriterTest.CLOCK,()->{reads.incrementAndGet();return f.open();},()->{},nanos::get,()->nanos.addAndGet(15_000_000_000L)));assertEquals(13,reads.get());nanos.set(0);assertThrows(RuntimeException.class,()->NativeClaimCloseWait.read(B,JournaledNativeWriterTest.CLOCK,()->{nanos.set(181_000_000_000L);return f.closed();},()->{},nanos::get,()->{}));}
 @Test void tamperUnknownChangedOwnerAndCancellationStop()throws Exception{var f=fixture(false,false);var other=fixture(false,false);var bad=f.open().copy();bad.sheet("accounts").rows.get(1).set(2,"tamper");var reads=new AtomicInteger();assertThrows(RuntimeException.class,()->NativeClaimCloseWait.read(B,JournaledNativeWriterTest.CLOCK,()->{reads.incrementAndGet();return bad;},()->{},()->0,()->{}));assertEquals(1,reads.get());assertThrows(Unknown.class,()->NativeClaimCloseWait.read(B,JournaledNativeWriterTest.CLOCK,()->{throw new Unknown();},()->{},()->0,()->{}));reads.set(0);assertThrows(RuntimeException.class,()->NativeClaimCloseWait.read(B,JournaledNativeWriterTest.CLOCK,()->reads.getAndIncrement()==0?f.open():other.closed(),()->{},()->0,()->{}));var closed=new AtomicBoolean();assertThrows(RuntimeException.class,()->NativeClaimCloseWait.read(B,JournaledNativeWriterTest.CLOCK,f::open,()->{if(closed.get())throw new Rejected();},()->0,()->closed.set(true)));}
 @Test void bootstrapHistoricalAdmissionThenFirstClaimWithEmptyOwnerCanClose()throws Exception{
  Book legacy=JournaledNativeWriterTest.initial().b.copy();legacy.metadata.clear();String account=legacy.sheet("accounts").rows.get(1).get(0);var original=com.bridge.persistence.HistoricalAdmissionTest.original(account);var envelope=new FinalMatchEnvelope(original.commitId(),original.matchId(),original.revision(),original.canonicalJson(),original.payloadHash());
  legacy.sheet("commits").rows=new ArrayList<>(List.of(ManualQuarterMaintenance.HEADERS.get("commits"),List.of(envelope.commitId(),envelope.payloadHash(),"1",envelope.matchId(),"1")));legacy.sheet("envelopes").rows=new ArrayList<>(List.of(ManualQuarterMaintenance.HEADERS.get("envelopes"),List.of(envelope.commitId(),envelope.payloadHash(),"0","1",envelope.canonicalJson())));
  var binding=JournaledNativeWriterTest.BINDING;var clock=JournaledNativeWriterTest.CLOCK;Book bootstrap=LegacyToNativeCutoverPlan.prepare(binding,legacy,clock).expected();String approval=UUID.randomUUID().toString();var admitted=HistoricalCasualAdmission.migrate(envelope,approval);var counts=LifetimeStatistics.fromEnvelopes(account,List.of(admitted)).casual();
  Book migrated=HistoricalCasualMigrationPlan.prepare(binding,bootstrap,new HistoricalCasualMigrationPlan.Approval(binding,NativeCommitJournal.digest(binding,bootstrap),envelope.commitId(),envelope.payloadHash(),approval,counts),clock).expected();assertEquals("",root(new ArrayList<>(migrated.metadata.values())).owner());
  var memory=new JournaledNativeWriterTest.Memory(migrated);try(var service=new Service(new JournaledNativeTransport(memory,binding,clock),clock,binding,"w-"+UUID.randomUUID(),Limits.defaults())){service.start();assertEquals(State.OPEN,service.state());Book open=memory.b.copy();assertEquals("",parse(open.metadata.get(4).value()).path("owner").asText());service.cleanClose();assertEquals(State.CLOSED,service.state());Book closed=memory.b.copy();var reads=new AtomicInteger();assertEquals(JournalSessionAuthority.fullToken(closed),JournalSessionAuthority.fullToken(NativeClaimCloseWait.read(B,clock,()->reads.getAndIncrement()==0?open:closed,()->{},()->0,()->{})));assertEquals(2,reads.get());}
 }
 @Test void forgedEmptyPreviousOwnerRejectedEvenWithValidCurrentDigest()throws Exception{
  Book forged=fixture(false,false).open().copy();Root root=root(new ArrayList<>(forged.metadata.values()));Metadata receipt=forged.metadata.get(root.next()-1);var value=(com.fasterxml.jackson.databind.node.ObjectNode)parse(receipt.value());value.put("owner","");forged.metadata.put(receipt.id(),new Metadata(receipt.id(),receipt.key(),json(value),receipt.sheet()));
  Metadata journal=forged.metadata.get(NativeCommitJournal.ID);var proof=(com.fasterxml.jackson.databind.node.ObjectNode)parse(journal.value());proof.put("afterDigest",NativeCommitJournal.digest(JournaledNativeWriterTest.BINDING,forged));forged.metadata.put(journal.id(),new Metadata(journal.id(),journal.key(),NativeCommitJournal.canonical(proof),journal.sheet()));NativeCommitJournal.verify(JournaledNativeWriterTest.BINDING,forged,JournaledNativeWriterTest.CLOCK);
  var reads=new AtomicInteger();assertThrows(RuntimeException.class,()->NativeClaimCloseWait.read(B,JournaledNativeWriterTest.CLOCK,()->{reads.incrementAndGet();return forged;},()->{},()->0,()->fail("must not wait on forged predecessor")));assertEquals(1,reads.get());
 }
 @Test void interruptBeforeAndAfterReadPreservesFlag()throws Exception{var f=fixture(false,false);var reads=new AtomicInteger();try{Thread.currentThread().interrupt();assertThrows(RuntimeException.class,()->NativeClaimCloseWait.read(B,JournaledNativeWriterTest.CLOCK,()->{reads.incrementAndGet();return f.closed();},()->{},()->0,()->{}));assertTrue(Thread.currentThread().isInterrupted());assertEquals(0,reads.get());}finally{Thread.interrupted();}try{assertThrows(RuntimeException.class,()->NativeClaimCloseWait.read(B,JournaledNativeWriterTest.CLOCK,()->{Thread.currentThread().interrupt();return f.closed();},()->{},()->0,()->{}));assertTrue(Thread.currentThread().isInterrupted());}finally{Thread.interrupted();}}
}
